sys_script.script:
(function executeRule(current, previous) {

    // ── Path 1: Regulatory Inspection bypass ────────────────────
    if (current.getValue('visit_type') == 'regulatory_inspection') {
        current.setValue('state', 'approved');
        gs.addInfoMessage(
            'EHS approval gate bypassed \u2014 visit type is Regulatory Inspection. ' +
            'Visit has been automatically approved.'
        );
        gs.info(
            'EHS Routing: Visit ' + current.getDisplayValue('number') +
            ' auto-approved (regulatory inspection bypass)'
        );
        return;
    }

    // ── Path 2: Check for restricted production zones ───────────
    var zoneList = current.getValue('production_zones');
    if (!zoneList) {
        return;
    }

    var restrictedZones = [];

    var zoneGr = new GlideRecord('x_snc_voltworksr_0_production_zone');
    zoneGr.addQuery('sys_id', 'IN', zoneList);
    zoneGr.addQuery('access_tier', 'restricted');
    zoneGr.query();

    while (zoneGr.next()) {
        restrictedZones.push(
            zoneGr.getDisplayValue('name') + ' (' + zoneGr.getValue('short_code') + ')'
        );
    }

    if (restrictedZones.length > 0) {
        current.setValue('state', 'pending_ehs_approval');
        gs.addInfoMessage(
            'Visit routed to EHS Approval \u2014 the following restricted zones were requested: ' +
            restrictedZones.join(', ') + '.'
        );
        gs.info(
            'EHS Routing: Visit ' + current.getDisplayValue('number') +
            ' held for EHS approval. Restricted zones: ' + restrictedZones.join(', ')
        );
    }

})(current, previous);
